/**
 * posture-lens.ts — 姿态透镜
 *
 * 单一职责：根据战略姿态，对 23 个现有诊断模块做三层适配：
 *   1. 选择 —— 哪些模块运行，哪些跳过
 *   2. 加权 —— 同一模块在不同姿态下的权重（用于报告排序和严重度计算）
 *   3. 翻译 —— 同一发现在不同姿态下的叙事语言
 *
 * 这是 ARCH-16 §3.2-3.5 的工程化简——不新建计算模块，在现有模块上叠加姿态透镜。
 */
import type { StrategicPosture, PostureConfig, ModuleFinding } from './types';
/** 给定姿态和候选模块列表，返回应启用的模块 ID 集合 */
export declare function filterModulesByPosture(posture: StrategicPosture, candidateModuleIds: string[]): {
    enabled: string[];
    skipped: string[];
};
/** 判断单个模块是否应在给定姿态下运行 */
export declare function isModuleEnabledForPosture(posture: StrategicPosture, moduleId: string): boolean;
/**
 * 将模块发现翻译为姿态特定的叙事。
 * 返回：
 *   - sectionTitle: 该模块在报告中的章节标题
 *   - narrative: 人类可读的叙事文本（替代原始的 detail）
 *   - severity: 可能因姿态阈值调整后的严重度
 */
export declare function translateFinding(posture: StrategicPosture, moduleId: string, finding: ModuleFinding, moduleScore?: number): {
    sectionTitle: string;
    narrative: string;
    severity: ModuleFinding['severity'];
};
/** 为 CEO 摘要生成姿态特定的叙事段落 */
export declare function translateAction(posture: StrategicPosture, moduleId: string, finding: ModuleFinding): string;
/** 根据姿态生成报告开场引导语 */
export declare function postureOpening(posture: StrategicPosture): string;
/** 获取姿态的完整配置（供编排器使用） */
export declare function loadPostureConfig(posture: StrategicPosture): PostureConfig;
